{
        let handled_event = ExtToolHandled({
          step: step_idx,
          stream_id: stream_id,
          tool: call.name,
          id: call.id,
          exit_code: result_env.exit_code
        });
        let _ = emit(handled_event); let waits = apply_tool_lifecycle(open_waits, call, result_env); let wait_diag = match wait_diagnostic_event(step_idx, call, result_env) { Some(d) => { let _ = emit(d); [d] }, None => [] }; -- PLAN-002 W2 Part 2 (ADR-002 D3): the wait is lifted from the ENVELOPE, before `handled_tool_message` caps the encoded message, and rides the fold as `open_waits`; an invalid one registers nothing and leaves its diagnostic in `emitted`. Joined onto this line so tool_phase.ail:499 does not move
        let scratch = emit_scratchpad_result_if_present(emit, "step-${show(step_idx)}", step_idx, call.id, result_env);
        { msg: handled_tool_message(call.id, result_env), next_state: handle_world, emitted: handled_event :: (wait_diag ++ scratch), open_waits: waits }
      },
      Delegate => {
        let backend = if ohmy_pi then backend_for_v2(envelope, true) else Native;
        match backend {
          Delegated => {
            let deferred_event = DelegatedToolDeferred({
              step: step_idx,
              stream_id: stream_id,
              tool: call.name,
              id: call.id
            });
            let _ = emit(deferred_event);
            -- `handle_world`, not `world`. A DELEGATING hook still ran — it may
            -- have performed effects before deciding it had nothing to offer, and
            -- `first_handle`'s own WI-B2b comment says so at the other end of the
            -- same seam. Only a hook that was never invoked passes the world
            -- through untouched, and `first_handle` already handles that case.
            { msg: delegated_deferred_message(call), next_state: handle_world, emitted: [deferred_event], open_waits: open_waits }
          },
          Native => {
            let start_event = V2ToolDispatchStart({
              step: step_idx,
              stream_id: stream_id,
              tool: call.name,
              id: call.id
            });
            let resolution = dispatch_resolution(handle_world.process_limits, call.name, envelope.arguments); let invalid_resolution = match resolution { Some(ProcessInvalid(_)) => resolution, _ => None }; let _ = match invalid_resolution { Some(_) => (), None => emit(start_event) }; -- 041 D7: pure, so it is resolved ahead of Start, and an invalid request has no Start. Joined here so :499 does not move
            -- THE ROUTED SITE. Before A12 this was a bare `dispatch_one`; the
            -- typed contract now carries the request, the deadline and a
            -- discriminated result. The deadline budget is read through the ENV
            -- class, so the world configures it rather than a constant.
            -- `handle_world`, not `world`: the delegating hook ran before this
            -- native dispatch, so starting the clock from `world` would discard
            -- whatever it did and then overwrite it with this call's successor.
            let started = ports.clock_now(handle_world);
            let budget = ports.env_get(advance(started.next_state, ClockRead), "MOTOKO_TOOL_TIMEOUT_MS", "0");
            -- 041 D7: `Limits` mode resolved a process tool above, ahead of Start and the
            -- port, so scripted and live see one answer. The env read above stays in both
            -- modes because the discovery recorders count it.
            match invalid_resolution {
              -- An invalid request never reaches the port, so nothing is served and no
              -- `ToolExec` is counted. It has its own event and neither Start nor Complete,
              -- so `corpus_judge`'s dispatch balance holds and P1 can see the refusal.
              Some(invalid) => {
                let invalid_event = ToolArgumentsInvalid({
                  step: step_idx,
                  stream_id: stream_id,
                  tool: call.name,
                  id: call.id
                });
                let _ = emit(invalid_event);
                {
                  msg: invalid_request_message(call, invalid, rejected_request_text(envelope.arguments)),
                  next_state: advance(budget.next_state, EnvRead),
                  emitted: [invalid_event],
                  open_waits: open_waits
                }
              },
              None => {
                let carrier = match resolution { Some(ProcessResolved(r)) => Some(r), _ => None };
                let invocation: ToolInvocation = {
                  call: envelope,
                  workdir: workdir,
                  timeout_ms: projected_timeout_ms(carrier, parse_timeout_ms(budget.value)),
                  started_at_ms: started.now_ms,
                  process: carrier
                };
                let execution = ports.tool_exec(advance(budget.next_state, EnvRead), invocation);
                let complete_event = V2ToolDispatchComplete({
                  step: step_idx,
                  stream_id: stream_id,
                  id: call.id
                });
                let _ = emit(complete_event);
                {
                  msg: tool_outcome_message(call, carrier, execution.outcome),
                  next_state: advance(execution.next_state, ToolExec),
                  -- START then COMPLETE, which is the order they happened in. The
                  -- driver appends this log positionally, so a reversal here is a
                  -- reversal in the returned trace.
                  emitted: [start_event, complete_event],
                  open_waits: open_waits
                }
              }
            }
          }
        }
      }

